add_filter( 'woocommerce_package_rates', 'perfectpixel_flat_rate_per_kg', 20, 2 );

function perfectpixel_flat_rate_per_kg( $rates, $package ) {
	$rate_id = trim( '{{per_kg_rate_id}}' );
	if ( ! isset( $rates[ $rate_id ] ) ) {
		return $rates;
	}
	$weight = 0.0;
	foreach ( $package['contents'] as $item ) {
		if ( $item['data']->needs_shipping() ) {
			$weight += (float) $item['data']->get_weight() * (int) $item['quantity'];
		}
	}
	$cost = max( (float) '{{per_kg_minimum}}', $weight * (float) '{{per_kg_cost}}' );
	$rate = $rates[ $rate_id ];
	$rate->set_cost( wc_format_decimal( $cost, wc_get_price_decimals() ) );
	if ( $rate->get_taxes() ) {
		$rate->set_taxes( WC_Tax::calc_shipping_tax( $cost, WC_Tax::get_shipping_tax_rates() ) );
	}
	return $rates;
}
